root=Path(__file__).resolve().parents[1]
qs=json.loads((root/'data/extracted.json').read_text());by={q['id']:q for q in qs}
def source(mod,num,page,name):
 p=root/'sources'/('CCNA Training » '+name+'.pdf');return {'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'question':num,'page':page,'method':'visual transcription checked against PDF'}
def choice(mod,num,page,name,prompt,options,ans,exp=''):
 q={'id':f'ccna-{mod:02d}-q{num:03d}','module':f'ccna-{mod:02d}','type':'choice','source':source(mod,num,page,name),'prompt':{'en':prompt},'options':[{'id':chr(97+i),'text':{'en':v}} for i,v in enumerate(options)],'answers':list(ans),'required':len(ans),'explanation':{'en':exp},'images':[],'verified':True,'translationStatus':'pending'};qs.append(q);by[q['id']]=q;return q
