# All matching exercises use permanent option and target IDs. Category values may be reused.
def match(mod,num,page,prompt,values,labels,solution,frprompt=None,frvalues=None,frlabels=None):
 q=by.get(f'ccna-{mod:02d}-q{num:03d}')
 if q is None:
  q={'id':f'ccna-{mod:02d}-q{num:03d}','module':f'ccna-{mod:02d}','source':source(mod,num,page,'Drag Drop Quiz 2'),'images':[],'explanation':{'en':''}};qs.append(q);by[q['id']]=q
 q.update(type='match',prompt={'en':prompt},options=[{'id':f'o{i+1}','text':{'en':v}} for i,v in enumerate(values)],targets=[{'id':f't{i+1}','text':{'en':v}} for i,v in enumerate(labels)],solution={f't{i+1}':f'o{v}' for i,v in enumerate(solution)},required=len(labels),answers=[],verified=True,translationStatus='pending')
 q['images']=[]
 if frprompt:
  q['prompt']['fr']=frprompt
  for o,v in zip(q['options'],frvalues or values):o['text']['fr']=v
  for o,v in zip(q['targets'],frlabels or labels):o['text']['fr']=v
 return q
